html { font-size: 16px; }

body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-brand);
  color: #fff;
  font-weight: 600;
  border-radius: 0 0 var(--radius-input) var(--radius-input);
  text-decoration: none;
  z-index: 100;
  transition: top .15s;
}
.skip-link:focus { top: 0; outline: 3px solid var(--color-brand-focus); outline-offset: 2px; }

/* ── Site header ── */
.site-header {
  width: 100%;
  padding: 1.25rem 2rem;
  display: flex;
  align-items: center;
  gap: .5rem;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}
.site-logo { font-size: 1.25rem; color: var(--color-brand); }
.site-name  { font-weight: 700; font-size: 1.05rem; letter-spacing: -.01em; }

/* ── Main layout ── */
main {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2.5rem 1rem;
  width: 100%;
}

/* ── Card ── */
.card {
  background: var(--color-surface);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 440px;
}

/* ── Form header ── */
.form-eyebrow {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-brand);
  margin-bottom: .5rem;
}
.form-title {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.25;
  margin-bottom: .5rem;
}
.form-description {
  font-size: .9375rem;
  color: var(--color-text-muted);
  line-height: 1.5;
  margin-bottom: 1.75rem;
}
.required-legend {
  font-size: .8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.25rem;
}
.required-star { color: var(--color-error); font-weight: 700; }

