.checkbox-label {
  font-size: .9375rem;
  line-height: 1.5;
  cursor: pointer;
}
.checkbox-label a {
  color: var(--color-brand);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.checkbox-label a:hover  { color: var(--color-brand-hover); }
.checkbox-label a:focus-visible {
  outline: 3px solid var(--color-brand-focus);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ── Helper text ── */
.helper-text {
  font-size: .8125rem;
  color: var(--color-text-muted);
  line-height: 1.4;
  padding-left: 2rem;   /* indent under checkbox */
}

/* ── Error message ── */
.error-message {
  display: none;
  font-size: .8125rem;
  font-weight: 500;
  color: var(--color-error);
  background: var(--color-error-bg);
  border: 1px solid var(--color-error-border);
  border-radius: var(--radius-input);
  padding: .5rem .75rem;
  line-height: 1.4;
