.success-banner {
  display: flex;
  align-items: flex-start;
  gap: .75rem;
  background: var(--color-success-bg);
  border: 1px solid var(--color-success-border);
  border-radius: var(--radius-card);
  padding: 1.5rem;
  font-size: .9375rem;
  color: var(--color-success);
  line-height: 1.5;
}
.success-icon {
  font-size: 1.25rem;
