  const html = fs.readFileSync('index.html', 'utf8');
  const css  = fs.readFileSync('style.css',  'utf8');
  const js   = fs.readFileSync('app.js',     'utf8');
  const inlined = html
    .replace('<link rel="stylesheet" href="style.css" />', `<style>${css}</style>`)
    .replace('<script src="app.js"></script>', `<script>${js}</script>`);

  const browser = await chromium.launch();
  let total = 0;

  // 1. Initial render
  let page = await browser.newPage();
  await page.setContent(inlined, { waitUntil: 'load' });
  total += await runAxe(page, 'initial render');
  await page.close();

  // 2. Error state — click submit without checking
  page = await browser.newPage();
  await page.setContent(inlined, { waitUntil: 'load' });
  await page.click('button[type="submit"]');
  await page.waitForTimeout(200);
  total += await runAxe(page, 'error state (submitted unchecked)');
  await page.close();

  // 3. Success state — check box then submit
  page = await browser.newPage();
  await page.setContent(inlined, { waitUntil: 'load' });
  await page.check('#agree-terms');
  await page.click('button[type="submit"]');
  await page.waitForTimeout(200);
  total += await runAxe(page, 'success state');
  await page.close();

  await browser.close();
  console.log(`\nTotal violations across all states: ${total}`);
  process.exit(total > 0 ? 1 : 0);
})();
